import {EVENTS_NAMES} from 'events/index';
import {addEventListener} from "helpers/events";
import {module} from "helpers/module";
import {MapOfferCard} from "views/factory/cards/offer/map";
import './index.less';

const {
    COMMON: {
        MODALS: {
            COMMON: {
                CLOSE,
            }
        }
    }
} = EVENTS_NAMES;

class OffersModal {
    constructor(element) {
        this.module = element;

        this.bind();
        this.init();
    }

    bind = () => {
        addEventListener(document,'j-event-map-yandex-components-view-all__get-visible-markers-data-complete', this.handleGetVisibleMarkersData);
        addEventListener(document, CLOSE, this.handleClose);
    }

    handleClose = () => {
        document.removeEventListener('j-event-map-yandex-components-view-all__get-visible-markers-data-complete', this.handleGetVisibleMarkersData);
    }

    handleGetVisibleMarkersData = (e) => {
        const {list} = e.detail;

        this.module.innerHTML = '';

        const formattedData = {};

        list.forEach(({placemark, placemarkData}) => {
            const productId = placemarkData.offer.product.id;

            if(!formattedData[productId]) {
                formattedData[productId] = {
                    placemarkList: [placemark],
                    placemarkData,
                }

                return;
            }

            formattedData[productId].placemarkList.push(placemark);
        });

        const htmlList = Object.values(formattedData).map((data) => MapOfferCard.createMapOfferCard(data));

        if(htmlList.length) {
            this.module.insertAdjacentHTML('beforeend', htmlList.join(''));

            MapOfferCard.init();
            document.dispatchEvent(new CustomEvent('j-event-module__update'));
            document.dispatchEvent(new CustomEvent('j-event-favorites-components-section__get-favorites-products', {
                detail: {
                    fromMemory: true,
                }
            }));
        } else {
            this.module.innerHTML = `
                <div style="margin-top: 20px; font-style: italic;">
                    В видимой области карты <span style="font-weight: 800;">товаров не найдено</span>, попробуйте переместить карту!
                </div>
                <div style="margin-top: 20px;">
                    <span style="font-weight: 800;">Поделитесь ссылкой на сайт</span> в социальных сетях и мессенджерах, чтобы&nbsp;на&nbsp;сайте было больше товаров!
                </div>
            `;
        }
    }

    init = () => {
        document.dispatchEvent(new CustomEvent('j-event-map-yandex-components-view-all__get-visible-markers-data'));
    }
}

module.initModule('j-modules-common-offers-modal', OffersModal);
